window.AUTH=window.AUTH||{};window.AUTH["17-1672"]={"d":"17-1672","id":"2018/17-1672","n":"United States v. Haymond","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2018-12-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1672/76420/20181217125903969_17-1672tsUnitedStates.pdf","side":"pet","n":109},{"k":"respondent","label":"Brief of respondent Andre Ralph Haymond","date":"2019-01-18","url":"https://www.supremecourt.gov/DocketPDF/17/17-1672/81131/20190118154034145_17-1672bs.pdf","side":"res","n":57},{"k":"reply","label":"Reply of petitioner United States","date":"2019-02-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-1672/88414/20190214130259033_17-1672tsrbUnitedStates.pdf","side":"pet","n":32}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1672_5hek.pdf","tr":true,"items":[{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"op":9,"ar":8,"sum":"The Court found that a defendant cannot be found guilty of a claim not included in the indictment.","sumSrc":"Oyez","by":{"0":"15, 29, 30, 47","1":"13, 19","2":"6, 8, 9, 21"}},{"t":"case","label":"Anderson v. Corall","cite":"263 U.S. 193","y":1923,"id":"scdb/1923-028","sc":1,"sum":"1. Mere lapse of time, without imprisonment or other restraint contemplated by law, does not constitute service of sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"26"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"op":30,"ar":18,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"0":"passim","1":"3, 16, 18, 19, 21, 25","2":"3, 6, 9, 21"}},{"t":"case","label":"Black v. Romano","cite":"471 U.S. 606","y":1985,"id":"1984/84-465","sc":1,"op":1,"ar":2,"sum":"Respondent, upon pleading guilty in a Missouri state court to controlled substance offenses, was put on probation and given suspended prison sentences. Two months later, he was arrested for and subsequently charged with leaving the scene of an automobile accident, a felony. After a hearing, the judge who had sentenced respondent, finding that respondent had violated his probation conditions by committing a felony, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 39","1":"24"}},{"t":"case","label":"Blakely v. Washington","cite":"542 U.S. 296","y":2004,"id":"2003/02-1632","sc":1,"op":4,"sum":"Rejecting the idea that “the jury need only find whatever facts the legislature chooses to label elements of the crime, and that those it labels sentencing factors—no matter how much they may increase the punishment—may be found by the judge”.","sumSrc":"opinion","by":{"0":"28, 29, 30, 31","1":"17, 20"}},{"t":"case","label":"Burns v. United States","cite":"287 U.S. 216","y":1932,"id":"scdb/1932-006","sc":1,"by":{"0":"35","1":"25, 27"}},{"t":"case","label":"Cunningham v. California","cite":"549 U.S. 270","y":2007,"id":"2006/05-6551","sc":1,"op":2,"sum":"The Court ruled 6-3 that California's Determinate Sentencing Law was inconsistent with the Sixth Amendment right to trial by jury.","sumSrc":"Oyez","by":{"0":"28, 29, 30, 52","1":"34"}},{"t":"case","label":"Dillon v. United States","cite":"560 U.S. 817","y":2010,"id":"2009/09-6338","sc":1,"sum":"The Court held that federal sentencing guidelines are binding when a district court imposes a new sentence under a revised guideline range.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Escoe v. Zerbst","cite":"295 U.S. 490","y":1935,"id":"scdb/1934-133","sc":1,"sum":"Holding that a federal probationer had a statutory right to a hearing before a judge, but observing that he may not “insist upon a trial in any strict or formal sense”.","sumSrc":"brief:0","by":{"0":"27","1":"26"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Gagnon v. Scarpelli","cite":"411 U.S. 778","y":1973,"id":"1972/71-1225","sc":1,"op":3,"ar":2,"sum":"The Court held that a previously sentenced probationer is entitled to a hearing when his probation is revoked.","sumSrc":"Oyez","by":{"0":"passim","1":"22, 24, 32","2":"3"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"op":2,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"2, 5, 12, 18, 19"}},{"t":"case","label":"Jones v. United States","cite":"526 U.S. 227","y":1999,"id":"1998/97-6203","sc":1,"sum":"Authored by Justice David H. Souter, the Court ruled that the federal carjacking law established three separate offenses by the specification of elements, each of which must be charged by indictment, proved beyond a reasonable doubt, and submitted to a jury for its verdict.","sumSrc":"Oyez","by":{"0":"40","1":"30","2":"12"}},{"t":"case","label":"Minnesota v. Murphy","cite":"465 U.S. 420","y":1984,"id":"1983/82-827","sc":1,"sum":"The Supreme Court held that admissions made to a probation officer about a crime unrelated to the probation are admissible in subsequent prosecution. A state may require a probationer to meet with his officer and discuss matters that may affect his probationary status, but this does not create an exception to the rule that one must assert the privilege against self-incrimination.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"op":9,"ar":6,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"0":"passim","1":"22, 23, 27, 35","2":"passim"}},{"t":"case","label":"Oregon v. Ice","cite":"555 U.S. 160","y":2009,"id":"2008/07-901","sc":1,"op":6,"sum":"Noting the jury’s historic role as a “bulwark” between the government and the accused “at the trial for an alleged offense” (emphasis added).","sumSrc":"opinion","by":{"0":"20, 29, 30, 31, 37, 39","1":"21","2":"4, 9, 21"}},{"t":"case","label":"Rothgery v. Gillespie Cnty.","cite":"554 U.S. 191","y":2008,"id":"2007/07-440","sc":1,"op":1,"sum":"In an 8-1 ruling, the Court held that a criminal defendant's initial appearance before a judge marks the beginning of the proceedings against him and triggers the defendant's Sixth Amendment right to counsel whether or not a prosecutor is aware of or involved in that appearance. This right to counsel applies whenever a defendant learns of the charges against him and has his liberty subject to restriction.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Samson v. California","cite":"547 U.S. 843","y":2006,"id":"2005/04-9728","sc":1,"sum":"In a 6-to-3 decision authored by Justice Clarence Thomas, the Supreme Court held that Samson \"did not have an expectation of privacy that society would recognize as legitimate.\" Parole allows convicted criminals out of prison before their sentence is completed.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Smith v. Doe","cite":"538 U.S. 84","y":2003,"id":"2002/01-729","sc":1,"sum":"The Court held that the Alaska Sex Offender Registration Act's retroactive application does not violate the Ex Post Facto Clause because the act is nonpunitive. The Court reasoned that the act was clearly intended as a civil, non-punitive means of identifying previous offenders for the protection of the public.","sumSrc":"Oyez","by":{"0":"54"}},{"t":"case","label":"Southern Union Co. v. United States","cite":"567 U.S. 343","y":2012,"id":"2011/11-94","sc":1,"op":2,"sum":"The Court held that the rule applied in Apprendi v. New Jersey, where the Sixth Amendment’s guarantee of a jury trial requires that any fact which increases the maximum punishment for a particular crime be proved to a jury, applies to the imposition of criminal fines.","sumSrc":"Oyez","by":{"0":"29, 30, 31, 52","1":"34","2":"4"}},{"t":"case","label":"United States v. Aspinall","cite":"389 F.3d 332","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/389/332/","by":{"0":"42"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"op":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"passim","1":"18, 19, 30, 31, 32, 33","2":"6, 22, 23"}},{"t":"case","label":"United States v. Boultinghouse","cite":"784 F.3d 1163","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/784/1163/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Carlton","cite":"442 F.3d 802","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/442/802/","op":2,"by":{"0":"41"}},{"t":"case","label":"United States v. Cordova","cite":"461 F.3d 1184","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/461/1184/","op":2,"by":{"0":"42","1":"25"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"United States v. Cunningham","cite":"607 F.3d 1264","y":2010,"url":"https://www.courtlistener.com/c/F.3d/607/1264/","by":{"0":"42"}},{"t":"case","label":"United States v. Dees","cite":"467 F.3d 847","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/467/847/","op":1,"by":{"0":"41"}},{"t":"case","label":"United States v. Gavilanes-Ocaranza","cite":"772 F.3d 624","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/624/","op":2,"by":{"0":"42","1":"28"}},{"t":"case","label":"United States v. Hall","cite":"419 F.3d 980","y":2005,"url":"https://www.courtlistener.com/c/F.3d/419/980/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Henry","cite":"852 F.3d 1204","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/1204/","op":1,"by":{"0":"43"}},{"t":"case","label":"United States v. Hinson","cite":"429 F.3d 114","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/429/114/","op":1,"by":{"0":"41","1":"25"}},{"t":"case","label":"United States v. House","cite":"501 F.3d 928","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/501/928/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Johnson","cite":"356 Fed. Appx. 785","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./356/785/","by":{"0":"41"}},{"t":"case","label":"United States v. Kebodeaux","cite":"570 U.S. 387","y":2013,"id":"2012/12-418","sc":1,"op":5,"sum":"The Court held that the Necessary and Proper Clause gave Congress the power to create federal crimes and regulate their punishment, as well as apply the Sex Offender Registration and Notification Act (SORNA) on a defendant.","sumSrc":"Oyez","by":{"0":"51, 54"}},{"t":"case","label":"United States v. Kelley","cite":"446 F.3d 688","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/446/688/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Kirby","cite":"418 F.3d 621","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/418/621/","by":{"0":"42"}},{"t":"case","label":"United States v. Knights","cite":"534 U.S. 112","y":2001,"id":"2001/00-1260","sc":1,"sum":"The Court held that the warrantless search of Knights, which was supported by reasonable suspicion and authorized by a condition of probation, was reasonable within the meaning of the Fourth Amendment.","sumSrc":"Oyez","by":{"0":"28, 38"}},{"t":"case","label":"United States v. McIntosh","cite":"630 F.3d 699","y":2011,"url":"https://www.courtlistener.com/c/F.3d/630/699/","op":1,"by":{"0":"42","2":"7"}},{"t":"case","label":"United States v. Meeks","cite":"25 F.3d 1117","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/25/1117/","by":{"0":"41"}},{"t":"case","label":"United States v. Murray","cite":"275 U.S. 347","y":1928,"id":"scdb/1927-076","sc":1,"sum":"When a person sentenced to imprisonment by a District Court has begun to serve his sentence, that court has no power under the Probation Act of March 4,1925, to grant him probation even though the term at which sentence was imposed had not expired.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"United States v. Owen","cite":"854 F.3d 536","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/854/536/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Ray","cite":"530 F.3d 666","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/530/666/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Reese","cite":"775 F.3d 1327","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/775/1327/","by":{"0":"42"}},{"t":"case","label":"United States v. Rondeau","cite":"430 F.3d 44","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/430/44/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Simtob","cite":"485 F.3d 1058","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/485/1058/","by":{"0":"51","2":"19"}},{"t":"case","label":"United States v. Spangle","cite":"626 F.3d 488","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/626/488/","op":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Sperling","cite":"699 Fed. Appx. 636","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./699/636/","sum":"Rejecting challenge to mandatory reimprisonment requirement in Section 3583(k) under plain-error review.","sumSrc":"brief:0","by":{"0":"47"}},{"t":"case","label":"United States v. Tippens","cite":"39 F.3d 88","y":1994,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/88/","by":{"0":"42"}},{"t":"case","label":"United States v. Ward","cite":"770 F.3d 1090","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/770/1090/","op":1,"sum":"Rejecting challenge to mandatory reimprisonment requirement in 18 U.S.C. 3583(g) (1988) because “supervised release revocation proceedings are not considered part of a criminal prosecution”.","sumSrc":"brief:0","by":{"0":"41, 47"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"op":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"54"}},{"t":"case","label":"United States v. Work","cite":"409 F.3d 484","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/409/484/","by":{"0":"41"}},{"t":"case","label":"Wolff v. McDonnell","cite":"418 U.S. 539","y":1974,"id":"1973/73-679","sc":1,"op":1,"sum":"The Supreme Court held that while prisoners are not entitled to full due process protections, disciplinary proceedings must include written notice to the defendant of the charges, a written statement of evidence, and the opportunity for an inmate to call witnesses and present evidence.","sumSrc":"Oyez","by":{"0":"19, 25, 27"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"2, 23","1":"1"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"passim","1":"1","2":"3, 4, 6, 9, 15"}},{"t":"law","label":"Pub. L. No. 109-248","url":"https://www.govinfo.gov/link/plaw/109/public/248","by":{"0":"11, 54","1":"12"}},{"t":"law","label":"Pub. L. No. 108-21","url":"https://www.govinfo.gov/link/plaw/108/public/21","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1999","by":{"0":"36","1":"27, 28"}},{"t":"usc","label":"34 U.S.C. § 20901","url":"https://www.law.cornell.edu/uscode/text/34/20901","by":{"0":"7"}},{"t":"usc","label":"42 U.S.C. § 16901","url":"https://www.law.cornell.edu/uscode/text/42/16901","by":{"0":"7"}},{"t":"usc","label":"34 U.S.C. § 20911","url":"https://www.law.cornell.edu/uscode/text/34/20911","subs":["(1)","(5)(A)(iii)"],"by":{"0":"7, 7"}},{"t":"usc","label":"34 U.S.C. § 20913","url":"https://www.law.cornell.edu/uscode/text/34/20913","subs":["(a)"],"by":{"0":"7"}},{"t":"usc","label":"18 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/18/1201","subs":["(g)"],"stext":{"head":"§1201. Kidnapping","paras":[[0,"(a) Whoever unlawfully seizes, confines, inveigles, decoys, kidnaps, abducts, or carries away and holds for ransom or reward or otherwise any person, except in the case of a minor by the parent thereof, when—"],[1,"(1) the person is willfully transported in interstate or foreign commerce, regardless of whether the person was alive when transported across a State boundary, or the offender travels in interstate or foreign commerce or uses the mail or any means, facility, or instrumentality of interstate or foreign commerce in committing or in furtherance of the commission of the offense;"],[1,"(2) any such act against the person is done within the special maritime and territorial jurisdiction of the United States;"],[1,"(3) any such act against the person is done within the special aircraft jurisdiction of the United States as defined in section 46501 of title 49;"],[1,"(4) the person is a foreign official, an internationally protected person, or an official guest as those terms are defined in section 1116(b) of this title; or"],[1,"(5) the person is among those officers and employees described in section 1114 of this title and any such act against the person is done while the person is engaged in, or on account of, the performance of official duties,"],[0,"shall be punished by imprisonment for any term of years or for life and, if the death of any person results, shall be punished by death or life imprisonment."],[0,"(b) With respect to subsection (a)(1), above, the failure to release the victim within twenty-four hours after he shall have been unlawfully seized, confined, inveigled, decoyed, kidnapped, abducted, or carried away shall create a rebuttable presumption that such person has been transported in interstate or foreign commerce. Notwithstanding the preceding sentence, the fact that the presumption under this section has not yet taken effect does not preclude a Federal investigation of a possible violation of this section before the 24-hour period has ended."],[0,"(c) If two or more persons conspire to violate this section and one or more of such persons do any overt act to effect the object of the conspiracy, each shall be punished by imprisonment for any term of years or for life."],[0,"(d) Whoever attempts to violate subsection (a) shall be punished by imprisonment for not more than twenty years."],[0,"(e) If the victim of an offense under subsection (a) is an internationally protected person outside the United States, the United States may exercise jurisdiction over the offense if (1) the victim is a representative, officer, employee, or agent of the United States, (2) an offender is a national of the United States, or (3) an offender is afterwards found in the United States. As used in this subsection, the United States includes all areas under the jurisdiction of the United States including any of the places within the provisions of sections 5 and 7 of this title and section 46501(2) of title 49. For purposes of this subsection, the term \"national of the United States\" has the meaning prescribed in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22))."],[0,"(f) In the course of enforcement of subsection (a)(4) and any other sections prohibiting a conspiracy or attempt to violate subsection (a)(4), the Attorney General may request assistance from any Federal, State, or local agency, including the Army, Navy, and Air Force, any statute, rule, or regulation to the contrary notwithstanding."],[0,"(g) Special Rule for Certain Offenses Involving Children.—"],[1,"(1) To whom applicable.—If—"],[2,"(A) the victim of an offense under this section has not attained the age of eighteen years; and"],[2,"(B) the offender—"],[3,"(i) has attained such age; and"],[3,"(ii) is not—"],[4,"(I) a parent;"],[4,"(II) a grandparent;"],[4,"(III) a brother;"],[4,"(IV) a sister;"],[4,"(V) an aunt;"],[4,"(VI) an uncle; or"],[4,"(VII) an individual having legal custody of the victim;"],[1,"the sentence under this section for such offense shall include imprisonment for not less than 20 years."],[1,"[(2) Repealed. Pub. L. 108–21, title I, §104(b), Apr. 30, 2003, 117 Stat. 653.]"],[0,"(h) As used in this section, the term \"parent\" does not include a person whose parental rights with respect to the victim of an offense under this section have been terminated by a final court order."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1201?type=usc&year=mostrecent&link-type=html"},"head":"§1201. Kidnapping","tname":"Crimes and Criminal Procedure","by":{"0":"6","1":"32"}},{"t":"usc","label":"18 U.S.C. § 1591","url":"https://www.law.cornell.edu/uscode/text/18/1591","subs":["(b)"],"stext":{"head":"§1591. Sex trafficking of children or by force, fraud, or coercion","paras":[[0,"(a) Whoever knowingly—"],[1,"(1) in or affecting interstate or foreign commerce, or within the special maritime and territorial jurisdiction of the United States, recruits, entices, harbors, transports, provides, obtains, advertises, maintains, patronizes, or solicits by any means a person; or"],[1,"(2) benefits, financially or by receiving anything of value, from participation in a venture which has engaged in an act described in violation of paragraph (1),"],[0,"knowing, or, except where the act constituting the violation of paragraph (1) is advertising, in reckless disregard of the fact, that means of force, threats of force, fraud, coercion described in subsection (e)(2), or any combination of such means will be used to cause the person to engage in a commercial sex act, or that the person has not attained the age of 18 years and will be caused to engage in a commercial sex act, shall be punished as provided in subsection (b)."],[0,"(b) The punishment for an offense under subsection (a) is—"],[1,"(1) if the offense was effected by means of force, threats of force, fraud, or coercion described in subsection (e)(2), or by any combination of such means, or if the person recruited, enticed, harbored, transported, provided, obtained, advertised, patronized, or solicited had not attained the age of 14 years at the time of such offense, by a fine under this title and imprisonment for any term of years not less than 15 or for life; or"],[1,"(2) if the offense was not so effected, and the person recruited, enticed, harbored, transported, provided, obtained, advertised, patronized, or solicited had attained the age of 14 years but had not attained the age of 18 years at the time of such offense, by a fine under this title and imprisonment for not less than 10 years or for life."],[0,"(c) In a prosecution under subsection (a)(1) in which the defendant had a reasonable opportunity to observe the person so recruited, enticed, harbored, transported, provided, obtained, maintained, patronized, or solicited, the Government need not prove that the defendant knew, or recklessly disregarded the fact, that the person had not attained the age of 18 years."],[0,"(d) Whoever obstructs, attempts to obstruct, or in any way interferes with or prevents the enforcement of this section, shall be fined under this title, imprisoned for a term not to exceed 25 years, or both."],[0,"(e) In this section:"],[1,"(1) The term \"abuse or threatened abuse of law or legal process\" means the use or threatened use of a law or legal process, whether administrative, civil, or criminal, in any manner or for any purpose for which the law was not designed, in order to exert pressure on another person to cause that person to take some action or refrain from taking some action."],[1,"(2) The term \"coercion\" means—"],[2,"(A) threats of serious harm to or physical restraint against any person;"],[2,"(B) any scheme, plan, or pattern intended to cause a person to believe that failure to perform an act would result in serious harm to or physical restraint against any person; or"],[2,"(C) the abuse or threatened abuse of law or the legal process."],[1,"(3) The term \"commercial sex act\" means any sex act, on account of which anything of value is given to or received by any person."],[1,"(4) The term \"participation in a venture\" means knowingly assisting, supporting, or facilitating a violation of subsection (a)(1)."],[1,"(5) The term \"serious harm\" means any harm, whether physical or nonphysical, including psychological, financial, or reputational harm, that is sufficiently serious, under all the surrounding circumstances, to compel a reasonable person of the same background and in the same circumstances to perform or to continue performing commercial sexual activity in order to avoid incurring that harm."],[1,"(6) The term \"venture\" means any group of two or more individuals associated in fact, whether or not a legal entity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1591?type=usc&year=mostrecent&link-type=html"},"head":"§1591. Sex trafficking of children or by force, fraud, or coercion","tname":"Crimes and Criminal Procedure","by":{"0":"6","1":"32"}},{"t":"usc","label":"18 U.S.C. § 1594","url":"https://www.law.cornell.edu/uscode/text/18/1594","subs":["(c)"],"by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/18/2241","subs":["(c)"],"stext":{"head":"§2241. Aggravated sexual abuse","paras":[[0,"(a) By Force or Threat.—Whoever, in the special maritime and territorial jurisdiction of the United States or in a Federal prison, or in any prison, institution, or facility in which persons are held in custody by direction of or pursuant to a contract or agreement with the head of any Federal department or agency, knowingly causes another person to engage in a sexual act—"],[1,"(1) by using force against that other person; or"],[1,"(2) by threatening or placing that other person in fear that any person will be subjected to death, serious bodily injury, or kidnapping;"],[0,"or attempts to do so, shall be fined under this title, imprisoned for any term of years or life, or both."],[0,"(b) By Other Means.—Whoever, in the special maritime and territorial jurisdiction of the United States or in a Federal prison, or in any prison, institution, or facility in which persons are held in custody by direction of or pursuant to a contract or agreement with the head of any Federal department or agency, knowingly—"],[1,"(1) renders another person unconscious and thereby engages in a sexual act with that other person; or"],[1,"(2) administers to another person by force or threat of force, or without the knowledge or permission of that person, a drug, intoxicant, or other similar substance and thereby—"],[2,"(A) substantially impairs the ability of that other person to appraise or control conduct; and"],[2,"(B) engages in a sexual act with that other person;"],[0,"or attempts to do so, shall be fined under this title, imprisoned for any term of years or life, or both."],[0,"(c) With Children.—Whoever crosses a State line with intent to engage in a sexual act with a person who has not attained the age of 12 years, or in the special maritime and territorial jurisdiction of the United States or in a Federal prison, or in any prison, institution, or facility in which persons are held in custody by direction of or pursuant to a contract or agreement with the head of any Federal department or agency, knowingly engages in a sexual act with another person who has not attained the age of 12 years, or knowingly engages in a sexual act under the circumstances described in subsections (a) and (b) with another person who has attained the age of 12 years but has not attained the age of 16 years (and is at least 4 years younger than the person so engaging), or attempts to do so, shall be fined under this title and imprisoned for not less than 30 years or for life. If the defendant has previously been convicted of another Federal offense under this subsection, or of a State offense or an offense under the Uniform Code of Military Justice that would have been an offense under any such provision had the offense occurred in a Federal prison, unless the death penalty is imposed, the defendant shall be sentenced to life in prison."],[0,"(d) State of Mind Proof Requirement.—In a prosecution under subsection (c) of this section, the Government need not prove that the defendant knew that the other person engaging in the sexual act had not attained the age of 12 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2241?type=usc&year=mostrecent&link-type=html"},"head":"§2241. Aggravated sexual abuse","tname":"Crimes and Criminal Procedure","by":{"0":"6","1":"32"}},{"t":"usc","label":"18 U.S.C. § 2242","url":"https://www.law.cornell.edu/uscode/text/18/2242","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/18/2243","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/18/2244","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2245","url":"https://www.law.cornell.edu/uscode/text/18/2245","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2250","url":"https://www.law.cornell.edu/uscode/text/18/2250","subs":["(2012)"],"by":{"0":"6, 12"}},{"t":"usc","label":"18 U.S.C. § 2251","url":"https://www.law.cornell.edu/uscode/text/18/2251","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2251A","url":"https://www.law.cornell.edu/uscode/text/18/2251A","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2252","url":"https://www.law.cornell.edu/uscode/text/18/2252","subs":["(a)(4)(B)","(b)(2)"],"stext":{"head":"§2252. Certain activities relating to material involving the sexual exploitation of minors","paras":[[0,"(a) Any person who—"],[1,"(1) knowingly transports or ships using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce by any means including by computer or mails, any visual depiction, if—"],[2,"(A) the producing of such visual depiction involves the use of a minor engaging in sexually explicit conduct; and"],[2,"(B) such visual depiction is of such conduct;"],[1,"(2) knowingly receives, or distributes, any visual depiction using any means or facility of interstate or foreign commerce or that has been mailed, or has been shipped or transported in or affecting interstate or foreign commerce, or which contains materials which have been mailed or so shipped or transported, by any means including by computer, or knowingly reproduces any visual depiction for distribution using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce or through the mails, if—"],[2,"(A) the producing of such visual depiction involves the use of a minor engaging in sexually explicit conduct; and"],[2,"(B) such visual depiction is of such conduct;"],[1,"(3) either—"],[2,"(A) in the special maritime and territorial jurisdiction of the United States, or on any land or building owned by, leased to, or otherwise used by or under the control of the Government of the United States, or in the Indian country as defined in section 1151 of this title, knowingly sells or possesses with intent to sell any visual depiction; or"],[2,"(B) knowingly sells or possesses with intent to sell any visual depiction that has been mailed, shipped, or transported using any means or facility of interstate or foreign commerce, or has been shipped or transported in or affecting interstate or foreign commerce, or which was produced using materials which have been mailed or so shipped or transported using any means or facility of interstate or foreign commerce, including by computer, if—"],[3,"(i) the producing of such visual depiction involves the use of a minor engaging in sexually explicit conduct; and"],[3,"(ii) such visual depiction is of such conduct; or"],[1,"(4) either—"],[2,"(A) in the special maritime and territorial jurisdiction of the United States, or on any land or building owned by, leased to, or otherwise used by or under the control of the Government of the United States, or in the Indian country as defined in section 1151 of this title, knowingly possesses, or knowingly accesses with intent to view, 1 or more books, magazines, periodicals, films, video tapes, or other matter which contain any visual depiction; or"],[2,"(B) knowingly possesses, or knowingly accesses with intent to view, 1 or more books, magazines, periodicals, films, video tapes, or other matter which contain any visual depiction that has been mailed, or has been shipped or transported using any means or facility of interstate or foreign commerce or in or affecting interstate or foreign commerce, or which was produced using materials which have been mailed or so shipped or transported, by any means including by computer, if—"],[3,"(i) the producing of such visual depiction involves the use of a minor engaging in sexually explicit conduct; and"],[3,"(ii) such visual depiction is of such conduct;"],[0,"shall be punished as provided in subsection (b) of this section."],[0,"(b)(1) Whoever violates, or attempts or conspires to violate, paragraph (1), (2), or (3) of subsection (a) shall be fined under this title and imprisoned not less than 5 years and not more than 20 years, but if such person has a prior conviction under this chapter, section 1591, chapter 71, chapter 109A, or chapter 117, or under the Uniform Code of Military Justice or the laws of any State relating to aggravated sexual abuse, sexual abuse, or abusive sexual conduct involving a minor or ward, or the production, possession, receipt, mailing, sale, distribution, shipment, or transportation of child pornography, or sex trafficking of children, such person shall be fined under this title and imprisoned for not less than 15 years nor more than 40 years."],[0,"(2) Whoever violates, or attempts or conspires to violate, paragraph (4) of subsection (a) shall be fined under this title or imprisoned not more than 10 years, or both, but if any visual depiction involved in the offense involved a prepubescent minor or a minor who had not attained 12 years of age, such person shall be fined under this title and imprisoned for not more than 20 years, or if such person has a prior conviction under this chapter, chapter 71, chapter 109A, or chapter 117, or under the Uniform Code of Military Justice or the laws of any State relating to aggravated sexual abuse, sexual abuse, or abusive sexual conduct involving a minor or ward, or the production, possession, receipt, mailing, sale, distribution, shipment, or transportation of child pornography, such person shall be fined under this title and imprisoned for not less than 10 years nor more than 20 years."],[0,"(c) Affirmative Defense.—It shall be an affirmative defense to a charge of violating paragraph (4) of subsection (a) that the defendant—"],[1,"(1) possessed less than three matters containing any visual depiction proscribed by that paragraph; and"],[1,"(2) promptly and in good faith, and without retaining or allowing any person, other than a law enforcement agency, to access any visual depiction or copy thereof—"],[2,"(A) took reasonable steps to destroy each such visual depiction; or"],[2,"(B) reported the matter to a law enforcement agency and afforded that agency access to each such visual depiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2252?type=usc&year=mostrecent&link-type=html"},"head":"§2252. Certain activities relating to material involving the sexual exploitation of minors","tname":"Crimes and Criminal Procedure","by":{"0":"6, 3, 4, 14, 43, 3, 4, 16, 46","1":"23"}},{"t":"usc","label":"18 U.S.C. § 2252A","url":"https://www.law.cornell.edu/uscode/text/18/2252A","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2260","url":"https://www.law.cornell.edu/uscode/text/18/2260","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2421","url":"https://www.law.cornell.edu/uscode/text/18/2421","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2422","url":"https://www.law.cornell.edu/uscode/text/18/2422","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2423","url":"https://www.law.cornell.edu/uscode/text/18/2423","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 2425","url":"https://www.law.cornell.edu/uscode/text/18/2425","by":{"0":"6"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(2)(A)","(a)(4)(B)","(a)(5)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"5, 5, 49","1":"21","2":"17, 17, 17"}},{"t":"usc","label":"18 U.S.C. § 3561","url":"https://www.law.cornell.edu/uscode/text/18/3561","by":{"0":"35"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(b)"],"by":{"0":"35, 8"}},{"t":"usc","label":"18 U.S.C. § 3565","url":"https://www.law.cornell.edu/uscode/text/18/3565","subs":["(a)","(a)(2)"],"stext":{"head":"§3565. Revocation of probation","paras":[[0,"(a) Continuation or Revocation.—If the defendant violates a condition of probation at any time prior to the expiration or termination of the term of probation, the court may, after a hearing pursuant to Rule 32.1 of the Federal Rules of Criminal Procedure, and after considering the factors set forth in section 3553(a) to the extent that they are applicable—"],[1,"(1) continue him on probation, with or without extending the term or modifying or enlarging the conditions; or"],[1,"(2) revoke the sentence of probation and resentence the defendant under subchapter A."],[0,"(b) Mandatory Revocation for Possession of Controlled Substance or Firearm or Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in section 3563(a)(3);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of probation prohibiting the defendant from possessing a firearm;"],[1,"(3) refuses to comply with drug testing, thereby violating the condition imposed by section 3563(a)(4); 1 or"],[1,"(4) as a part of drug testing, tests positive for illegal controlled substances more than 3 times over the course of 1 year;"],[0,"the court shall revoke the sentence of probation and resentence the defendant under subchapter A to a sentence that includes a term of imprisonment."],[0,"(c) Delayed Revocation.—The power of the court to revoke a sentence of probation for violation of a condition of probation, and to impose another sentence, extends beyond the expiration of the term of probation for any period reasonably necessary for the adjudication of matters arising before its expiration if, prior to its expiration, a warrant or summons has been issued on the basis of an allegation of such a violation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3565?type=usc&year=mostrecent&link-type=html"},"head":"§3565. Revocation of probation","tname":"Crimes and Criminal Procedure","by":{"0":"35","1":"27"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(c)(2)"],"by":{"0":"45"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(b)","(c)","(d)","(e)(1988)","(e)(3)","(g)(1988)","(g)","(h)","(k)","(e)","(e)(3)(1994)","(g)(1994)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"40, 40, 40, 40, 40, 40, 47, 47, 9, 9, 9, 9","1":"16, 20, 20, 20, 30, passim, 33, 2, 16, 18, 22","2":"7, 8, 10, 6, 7, 8, 17, 14, passim, 13, 9, 13, passim"}},{"t":"usc","label":"18 U.S.C. § 3602","url":"https://www.law.cornell.edu/uscode/text/18/3602","by":{"0":"9"}},{"t":"usc","label":"18 U.S.C. § 3603","url":"https://www.law.cornell.edu/uscode/text/18/3603","subs":["(1)","(3)"],"by":{"0":"9, 9"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(b)"],"by":{"0":"5"}},{"t":"usc","label":"21 U.S.C. § 960","url":"https://www.law.cornell.edu/uscode/text/21/960","subs":["(b)"],"by":{"0":"5"}},{"t":"rule","label":"Fed. R. Crim. P. 32.1","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32.1","by":{"0":"10, 13, 35, 53","2":"16, 21"}},{"t":"case","label":"Bloom v. Illinois","cite":"391 U.S. 194","y":1968,"id":"1967/52","sc":1,"ar":2,"sum":"Petitioner was convicted in Illinois of criminal contempt and sentenced to 24 months' imprisonment for willfully petitioning to admit to probate a will falsely prepared and executed after the putative testator's death. His request for a jury trial was refused by the trial court. The Illinois Supreme Court affirmed his. conviction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 28"}},{"t":"case","label":"Callan v. Wilson","cite":"127 U.S. 540","y":1888,"id":"scdb/1887-273","sc":1,"ar":1,"sum":"The provision in article 3 of the Constitution of the United States that “the trial of all crimes, except in cases of impeachment, shall he by jury,” is to be construed in the light of the principles which, at common law, determined whether or not a person accused of crime was entitled to be tried by a jury; and thus construed, it embraces not only felonies punishable by confinement in the penitentiary, but also …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Cheff v. Schnackenberg","cite":"384 U.S. 373","y":1966,"id":"1965/67","sc":1,"sum":"The judgment is affirmed. Pp. 375-384. 341 F. 2d 548, affirmed. MR. JUSTICE CArK, joined by THE CHIEF JUSTICE, MR. JUSTICE BRENNAN, and Ma. JUSTICE FoRTAs, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Frank v. United States","cite":"395 U.S. 147","y":1969,"id":"1968/200","sc":1,"ar":1,"sum":"Petitioner was charged with criminal contempt for violating an injunction. After unsuccessfully demanding a jury trial, he was tried and adjudged guilty by the District Court, which suspended imposition of sentence and placed him on probation for three years. The Court of Appeals aflirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Gozlon-Peretz v. United States","cite":"498 U.S. 395","y":1991,"id":"1990/89-7370","sc":1,"sum":"Supervised release applies for all drug offenses in the categories specified by ADAA § 1002 that were committed after the ADAA was enacted but before November 1, 1987.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Graham v. Florida","cite":"560 U.S. 48","y":2010,"id":"2009/08-7412","sc":1,"sum":"The Court found that a non-homicidal conviction leading to a life sentence without parole for a juvenile violates the Eighth Amendment.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Harmelin v. Michigan","cite":"501 U.S. 957","y":1991,"id":"1990/89-7272","sc":1,"sum":"The Court, in a 5-to-4 decision, held that since the Eighth Amendment does not contain a proportionality guarantee, the determination of whether a punishment is \"cruel and unusual\" is not made with reference to the particular offense. Moreover, the Cruel and Unusual Punishment Clause protects against unusual methods of punishment, not necessarily cruel ones.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Middendorf v. Henry","cite":"425 U.S. 25","y":1976,"id":"1974/74-175","sc":1,"sum":"The Uniform Code of Military Justice (UCMJ) provides four methods of disposing of cases involving servicemen's offenses: general, special, and summary courts-martial, and disciplinary punishment pursuant to Art. 15 of the UCMJ. General courtsmartial and special courts-martial, which may impose substantial penalties, resemble judicial proceedings, nearly always presided over by lawyer judges, with lawyer counsel for …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Ring v. Arizona","cite":"536 U.S. 584","y":2002,"id":"2001/01-488","sc":1,"ar":1,"sum":"The Court held that, because Arizona's enumerated aggravating factors operates as \"the functional equivalent of an element of a greater offense,\" the Sixth Amendment requires that they be found by a jury.","sumSrc":"Oyez","by":{"1":"3, 18, 20"}},{"t":"case","label":"United States v. Apodaca","cite":"641 F.3d 1077","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/641/1077/","by":{"1":"32"}},{"t":"case","label":"United States v. Bari","cite":"599 F.3d 176","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/599/176/","by":{"1":"23"}},{"t":"case","label":"United States v. Charles","cite":"531 F.3d 637","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/637/","by":{"1":"23"}},{"t":"case","label":"United States v. Comstock","cite":"560 U.S. 126","y":2010,"id":"2009/08-1224","sc":1,"sum":"The Court held that the Necessary and Proper Clause granted Congress authority to enact the Adam Walsh Protection and Safety Act.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"United States v. Dixon","cite":"509 U.S. 688","y":1993,"id":"1992/91-1231","sc":1,"sum":"Justice Scalia noted that Grady was wrongly decided and must be overruled. Chief Justice William H. Rehnquist, Justice Sandra Day O’Connor, Justice Anthony M. Kennedy, and Justice Clarence Thomas joined in the judgment. Chief Justice Rehnquist concurred in part and dissented in part, writing that the subsequent prosecutions did not violate double jeopardy under the same elements test.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"United States v. Haymond","cite":"672 F.3d 948","y":2012,"url":"https://www.courtlistener.com/c/F.3d/672/948/","by":{"1":"4, 5"}},{"t":"case","label":"United States v. Helton","cite":"782 F.3d 148","y":2015,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/782/148/","sum":"Noting that 79% of non-production cases involve 600 or more images.","sumSrc":"brief:1","by":{"1":"4"}},{"t":"case","label":"United States v. Huerta-Pimental","cite":"445 F.3d 1220","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/445/1220/","op":1,"by":{"1":"25"}},{"t":"case","label":"United States v. Jackson","cite":"390 U.S. 570","y":1968,"id":"1967/85","sc":1,"sum":"The death penalty clause imposes an impermissible burden upon the exercise of a constitutional right, but that provision is severable from the remainder of the Act and the unconstitutionality of that clause does not require the defeat of the Act as a whole. Pp. 572-591. 262 F. Supp. 716, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"op":2,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"usc","label":"18 U.S.C. § 3559","url":"https://www.law.cornell.edu/uscode/text/18/3559","by":{"1":"22"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"1":"28"}},{"t":"law","label":"Pub. L. No. 100-182","url":"https://www.govinfo.gov/link/statute/101/1266","by":{"1":"28"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"1":"1, 16"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"United States v. Miqbel","cite":"444 F.3d 1173","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/444/1173/","by":{"2":"18"}},{"t":"case","label":"United States v. Mulero-Algarín","cite":"866 F.3d 8","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/866/8/","by":{"2":"18"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"sum":"The Court held that the Act was constitutional because when the government's interest in protecting the community outweighs individual liberty, pre-trial detention can be \"a potential solution to a pressing societal problem.\" The Act only applied to a specific list of serious offenses, placed heavy burdens on the government to prove that the arrestee posed significant threats to others, and did not prevent the accused from enjoying a speedy trial.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"United States v. Tyson","cite":"413 F.3d 824","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/413/824/","by":{"2":"18"}},{"t":"case","label":"United States v. Vigil","cite":"696 F.3d 997","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/696/997/","by":{"2":"18"}},{"t":"case","label":"United States v. Wood","cite":"299 U.S. 123","y":1936,"id":"scdb/1936-033","sc":1,"sum":"1. Bias of a prospective juror may be actual or implied; i. e., bias in fact or bias conclusively presumed as a matter of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"United States v. Young","cite":"634 F.3d 233","y":2011,"url":"https://www.courtlistener.com/c/F.3d/634/233/","sum":"Explaining that reimprisonment term would be unreasonable if district court “place[d] undue weight on the seriousness of the violation”.","sumSrc":"brief:2","by":{"2":"18, 19"}}]};